typedef long long LL;
typedef long double LD;

int cond = 1;

LL solve() {
  LL n, tmp;
  cin >> tmp;
  vector<int> d;
  n = tmp;
  if (n < 10) {
    return n;
  }
  while (n > 0) {
    d.push_back(n % 10);
    n /= 10;
  }
  int l = d.size();
  int prev = 0;
  int i = l - 1;
  for (; i >= 0; --i) {
    if (d[i] >= prev) {
      prev = d[i];
    } else {
      break;
    }
  }
  if (i < 0) {
    return tmp;
  }
  for (int j = i + 1; j < l; ++j) {
    if (d[j] > 0) {
      d[j]--;
    }
    if (j < l - 1 && d[j + 1] <= d[j]) {
      break;
    }
    if (j < l - 1) {
      i++;
    }
  }
  for (int j = 0; j <= i; ++j) {
    d[j] = 9;
  }
  long long r = 0;
  for (int i = l - 1; i >= 0; --i) {
    r *= 10;
    r += d[i];
  }
  return r;
}

int main() {
  int t;
  cin >> t;
  for (int x = 1; x <= t; ++x) {
    cout << "Case #" << x << ": " << solve() << endl; // result
  }
  return 0;
}
