            carry = 1;
            str[i] = '9';
          }

          i--;
        }

        for (int j = 0; j <= idx; j++) {
          if (j == 0 && str[j] == '0')
            continue;
          printf("%c", str[j]);
        }

        for (int j = idx + 1; j < len; j++) {
          printf("9");
        }
        printf("\n");
        break;
      }
    }

    if (valid) {
      printf("%s\n", str);
    }

    cerr << "Test " << ct << " done \n";
  }
  return 0;
}
